import pyomo.environ as pyo

DATA = {
    "weeks": list(range(1, 20)),
    "fixed_cost": {
        1: 930, 2: 881, 3: 925, 4: 808, 5: 711, 6: 785, 7: 997,
        8: 820, 9: 843, 10: 631, 11: 726, 12: 1071, 13: 741,
        14: 1157, 15: 916, 16: 791, 17: 1055, 18: 932, 19: 794,
    },
    "var_cost": {
        1: 40, 2: 26, 3: 38, 4: 20, 5: 25, 6: 22, 7: 40,
        8: 39, 9: 25, 10: 26, 11: 34, 12: 25, 13: 26,
        14: 27, 15: 27, 16: 35, 17: 23, 18: 26, 19: 36,
    },
    "hold_cost": {
        1: 19, 2: 16, 3: 24, 4: 23, 5: 24, 6: 23, 7: 20,
        8: 21, 9: 21, 10: 25, 11: 15, 12: 20, 13: 24,
        14: 16, 15: 16, 16: 16, 17: 19, 18: 15, 19: 20,
    },
    "back_cost": {
        1: 55, 2: 54, 3: 71, 4: 58, 5: 51, 6: 55, 7: 45,
        8: 52, 9: 60, 10: 52, 11: 52, 12: 52, 13: 76,
        14: 50, 15: 47, 16: 66, 17: 70, 18: 48, 19: 69,
    },
    "demand": {
        1: 495, 2: 316, 3: 375, 4: 467, 5: 418, 6: 398, 7: 533,
        8: 525, 9: 361, 10: 452, 11: 470, 12: 378, 13: 302,
        14: 463, 15: 438, 16: 383, 17: 377, 18: 429, 19: 324,
    },
    "total_demand": 7904,
    "last_week": 19,
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.T = pyo.Set(initialize=d["weeks"], ordered=True)

    model.order = pyo.Var(
        model.T, within=pyo.NonNegativeReals, bounds=(0, d["total_demand"])
    )
    model.place = pyo.Var(model.T, within=pyo.Binary)
    model.inventory = pyo.Var(model.T, within=pyo.NonNegativeReals)
    model.backlog = pyo.Var(model.T, within=pyo.NonNegativeReals)

    # Objective: minimize fixed + variable ordering + holding + backlog costs
    def obj_rule(m):
        return (
            sum(d["fixed_cost"][t] * m.place[t] for t in m.T)
            + sum(d["var_cost"][t] * m.order[t] for t in m.T)
            + sum(d["hold_cost"][t] * m.inventory[t] for t in m.T)
            + sum(d["back_cost"][t] * m.backlog[t] for t in m.T)
        )

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Inventory balance for each week (inventory[0] = backlog[0] = 0)
    def balance_rule(m, t):
        prev_inv = m.inventory[t - 1] if t - 1 in m.T else 0
        prev_back = m.backlog[t - 1] if t - 1 in m.T else 0
        return (
            prev_inv + m.order[t] + m.backlog[t]
            == d["demand"][t] + m.inventory[t] + prev_back
        )

    model.balance = pyo.Constraint(model.T, rule=balance_rule)

    # Order quantity cannot exceed total demand if an order is placed
    def order_limit_rule(m, t):
        return m.order[t] <= d["total_demand"] * m.place[t]

    model.order_limit = pyo.Constraint(model.T, rule=order_limit_rule)

    # Final inventory must be zero
    def final_inventory_rule(m):
        return m.inventory[d["last_week"]] == 0

    model.final_inventory = pyo.Constraint(rule=final_inventory_rule)

    # Final backlog must be zero
    def final_backlog_rule(m):
        return m.backlog[d["last_week"]] == 0

    model.final_backlog = pyo.Constraint(rule=final_backlog_rule)

    return model


